// Keep only carts that are due a reminder:
//   - Reminder Sent is still empty (never reminded before), AND
//   - the cart's Timestamp is more than 1 hour old, AND
//   - the row has a plausible email address.
// If nothing is due, return [] and the workflow quietly stops —
// no empty emails, no noise.
const ONE_HOUR_MS = 60 * 60 * 1000;
const cutoff = Date.now() - ONE_HOUR_MS;
const due = [];
for (const item of $input.all()) {
  const j = item.json;
  const reminded = String(j['Reminder Sent'] || '').trim();
  if (reminded) continue;
  const email = String(j['Email'] || '').trim();
  if (!email.includes('@')) continue;
  const ts = new Date(j['Timestamp']).getTime();
  if (isNaN(ts) || ts > cutoff) continue;
  due.push(item);
}
return due;
